def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 2:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(bid)

    if not alive_opponents:
        return max(0, min(budget, DAILY_SALARY * 0.35))

    high_supply = supply >= 22
    low_supply = supply <= 17

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0
        avg_prev = 0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 2

    pressure = 0
    if highest_prev >= DAILY_SALARY * 0.9:
        pressure += 3
    elif highest_prev >= DAILY_SALARY * 0.7:
        pressure += 2
    elif highest_prev >= DAILY_SALARY * 0.45:
        pressure += 1

    if urgent_opp >= 2:
        pressure += 1
    if rich_opp >= 2:
        pressure += 1
    if low_supply:
        pressure += 2
    elif high_supply:
        pressure -= 1

    if danger >= 5:
        target = DAILY_SALARY * 0.96
    elif danger >= 3:
        target = DAILY_SALARY * 0.82
    elif pressure >= 5:
        target = max(DAILY_SALARY * 0.72, highest_prev + 2)
    elif pressure >= 3:
        target = max(DAILY_SALARY * 0.58, avg_prev + 1.5)
    elif high_supply:
        target = DAILY_SALARY * 0.34
    else:
        target = DAILY_SALARY * 0.48

    if budget < DAILY_SALARY * 0.6 and danger <= 2:
        target = min(target, DAILY_SALARY * 0.42)
    if budget < DAILY_SALARY * 0.35:
        target = min(target, budget)

    target = max(0, min(budget, target))
    return target

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = [o for o in opponents_status.values() if o.get('alive')]

    # If no opponent info, bid based on our urgency and likely competition.
    urgency = 0.0
    if no_water_days >= 2:
        urgency = 0.35
    elif no_water_days == 1:
        urgency = 0.18

    # Base bid: aim around one unit of requirement share.
    # With supply in [15,25], competition likely means we should bid moderately.
    supply_ratio = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    if hp <= 2:
        base = DAILY_SALARY * (0.70 + 0.25 * supply_ratio)
    elif hp <= 3:
        base = DAILY_SALARY * (0.55 + 0.20 * supply_ratio)
    else:
        base = DAILY_SALARY * (0.45 + 0.15 * supply_ratio)

    # If we had yesterday bids, react. (Yesterday context may be missing; handle safely.)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If they were aggressive yesterday, slightly outbid; otherwise bid near base.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            base = max(base, highest_prev_bid * 1.05)
        elif highest_prev_bid >= DAILY_SALARY * 0.55:
            base = max(base, highest_prev_bid * 0.95)
        else:
            base = max(base, highest_prev_bid + 1.0)

    # Add urgency bump.
    base = base * (1.0 + urgency)

    # Never exceed what we can pay.
    # Also cap to avoid burning budget early.
    cap = min(budget, DAILY_SALARY * (0.95 if hp <= 3 else 0.75))
    bid = min(cap, base)

    # Ensure non-negative and at least a small bid.
    if bid < 0:
        bid = 0.0
    if bid == 0.0 and budget > 0:
        bid = min(budget, DAILY_SALARY * 0.15)

    return float(bid)
